INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Representation letter addressee
(1, 'Written Representations', 'During the audit of Quail Ridge Manufacturing for the year ended December 31, 2025, the controller prepares the management representation letter. The controller asks the engagement partner at Prescott & Associates to whom the letter should be addressed. Under AU-C 580, the management representation letter should be addressed to:', '["The auditor or the audit firm", "The entity''s board of directors", "The entity''s external legal counsel", "The Securities and Exchange Commission"]'::jsonb, 0, 'Under AU-C 580.15, the written representation letter is addressed to the auditor. The letter is a direct communication from management to the engagement team, confirming matters discussed during the audit. Addressing it to the board is incorrect because the representation letter serves an evidentiary purpose for the auditor, unlike governance communications directed to the board or regulatory filings sent to the SEC.', 'medium', 3),

-- Q2: easy / L2 — Period covered by the representation letter
(1, 'Written Representations', 'Talbot & Associates is auditing Riverview Corp.''s financial statements for the years ended December 31, 2024 and 2025 (comparative statements). The controller asks what periods the management representation letter should cover. Under AU-C 580, the letter should cover:', '["Only the most recent fiscal year", "All periods covered by the auditor''s report", "Only the period in which new transactions occurred", "All periods since the entity''s incorporation"]'::jsonb, 1, 'Under AU-C 580.14, when comparative financial statements are presented, the written representation letter should cover all periods referred to in the auditor''s report. If the auditor reports on two years, representations must extend to both years. Covering only the current year is incorrect because it would leave the prior-period assertions unsupported by management''s written acknowledgment.', 'easy', 2),

-- Q3: medium / L3 — Management's responsibility for fair presentation
(1, 'Written Representations', 'The CFO of Lakewood Industries asks the engagement partner at Barrett & Coleman what management is acknowledging when signing the representation letter for the December 2025 audit. Under AU-C 580, a key required representation is that management acknowledges:', '["That the auditor bears primary responsibility for the financial statements", "That the financial statements have been independently verified as error-free", "Its responsibility for the fair presentation of the financial statements in accordance with the applicable framework", "That the financial statements have been approved by the SEC before issuance"]'::jsonb, 2, 'Under AU-C 580.10, management must represent that it has fulfilled its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. Stating that the auditor bears primary responsibility is incorrect because the financial statements are management''s responsibility; the auditor provides an opinion but does not assume ownership of the statements.', 'medium', 3),

-- Q4: medium / L3 — Completeness of information provided (access to records)
(1, 'Written Representations', 'While finalizing the representation letter for the December 2025 audit of Granite Peak Logistics, the engagement partner at Wellington & Hart includes a representation about completeness of information. Under AU-C 580.11, management should specifically represent that it has provided the auditor with:', '["Only those records that management considers material", "Summaries of all transactions exceeding a specified dollar threshold", "Records selected by management as most relevant to the audit scope", "Access to all information relevant to the preparation of the financial statements"]'::jsonb, 3, 'Under AU-C 580.11, management must represent that it has provided the auditor with access to all information of which management is aware that is relevant to the preparation and fair presentation of the financial statements. Limiting the representation to material items is incorrect because the completeness assertion requires unrestricted access, and materiality determinations rest with the auditor, not management.', 'medium', 3),

-- Q5: easy / L1 — Definition of written representations
(1, 'Written Representations', 'Under AU-C 580, how are written representations defined in auditing standards?', '["Written statements provided by management to the auditor to confirm certain matters or support other audit evidence", "External confirmations sent by third parties to verify account balances", "Legal opinions provided by the entity''s external legal counsel", "Engagement letters signed by the auditor before the audit begins"]'::jsonb, 0, 'Under AU-C 580.05, written representations are written statements by management provided to the auditor to confirm certain matters or to support other audit evidence. They are a required element of every audit. External confirmations are incorrect because they are responses from third parties under AU-C 505, not management communications, and serve a different evidentiary purpose.', 'easy', 1),

-- Q6: medium / L2 — Representations about estimates and assumptions
(1, 'Written Representations', 'The engagement team at Crawford & Ellis is finalizing the management representation letter for the December 2025 audit of Silverline Pharmaceuticals, which has significant fair value estimates. Under AU-C 580, management should represent that:', '["The auditor has independently verified all estimates and assumptions", "The methods, significant assumptions, and data used in making accounting estimates are reasonable", "All accounting estimates will prove to be accurate within 5% of actual outcomes", "The auditor has approved the assumptions underlying all material estimates"]'::jsonb, 1, 'Under AU-C 580.12, management should represent that it believes the significant assumptions used in making accounting estimates are reasonable, including the methods and data underlying the estimates. Stating that the auditor approved the assumptions is incorrect because the responsibility for selecting methods and assumptions rests with management; the auditor evaluates but does not approve them.', 'medium', 2),

-- Q7: medium / L2 — Selection and application of accounting policies
(1, 'Written Representations', 'During the December 2025 audit of Cascade Timber Holdings, the engagement partner at Mitchell & Rhodes includes representations about the entity''s accounting framework. Under AU-C 580, management should represent that:', '["All accounting policies were selected to minimize reported liabilities", "The auditor prescribed which accounting policies to adopt", "The selection and application of accounting policies are appropriate", "Accounting policies must match the auditor''s stated preferences"]'::jsonb, 2, 'Under AU-C 580.10, management must represent that the financial statements are prepared in accordance with the applicable financial reporting framework, which requires that accounting policies are appropriately selected and applied. Stating that the auditor prescribed the policies is incorrect because management is responsible for choosing policies that conform to the framework, and the auditor evaluates but does not direct those choices.', 'medium', 2),

-- Q8: easy / L1 — Oral vs. written representations
(1, 'Written Representations', 'Under AU-C 580, why must representations from management be obtained in written form rather than orally?', '["Oral representations are prohibited by securities law", "Written representations are more convenient for management to provide", "Written representations are more expensive to prepare, signaling management commitment", "Written form reduces misunderstandings and provides a documented record for the audit file"]'::jsonb, 3, 'Under AU-C 580.A3, written representations reduce the possibility of misunderstandings between management and the auditor. A documented letter becomes part of the audit file and provides clear evidence of specific assertions. Claiming that oral representations are prohibited by securities law is incorrect because the written requirement stems from auditing standards, not securities legislation.', 'easy', 1),

-- Q9: easy / L1 — Representation letter as audit evidence classification
(1, 'Written Representations', 'Under AU-C 580, a signed management representation letter is classified as what type of audit evidence?', '["Internal evidence in written form", "External documentary evidence", "Corroborative physical evidence", "Analytical evidence derived from financial data"]'::jsonb, 0, 'Under AU-C 580.04, written representations are information provided by management to the auditor, making them internal evidence in written form. Although required on every audit, they are less reliable than external evidence such as third-party confirmations. External documentary evidence is incorrect because the representation letter originates from within the entity, not from an independent outside source.', 'easy', 1),

-- Q10: medium / L2 — Completeness of litigation and claims
(1, 'Written Representations', 'The audit team at Fletcher & Morgan includes litigation representations in the management representation letter for Oakmont Holdings'' December 2025 audit. Under AU-C 580, management should represent that it has disclosed to the auditor:', '["Only litigation in which the entity is the defendant", "All known actual or possible litigation and claims whose effects should be considered in the financial statements", "Only litigation with probable outcomes exceeding materiality", "All litigation that has been formally filed in court"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that it has disclosed all known actual or possible litigation and claims whose effects should be considered when preparing the financial statements. Restricting disclosure to formally filed lawsuits is incorrect because the standard also covers threatened litigation and claims not yet filed, which could materially affect the financial statements.', 'medium', 2),

-- Q11: easy / L1 — Written representations not sufficient alone
(1, 'Written Representations', 'Under AU-C 580, can written representations serve as the auditor''s sole basis for concluding on a financial statement assertion?', '["Yes, written representations are the most reliable form of audit evidence", "Yes, provided management has signed the letter without qualification", "No, written representations are necessary but not sufficient appropriate audit evidence by themselves", "No, because written representations are optional and carry no evidentiary weight"]'::jsonb, 2, 'Under AU-C 580.04, written representations provide necessary audit evidence but do not provide sufficient appropriate audit evidence on their own about any of the matters with which they deal. The auditor must corroborate representations with other procedures. Stating that they carry no evidentiary weight is incorrect because representations are required evidence — they are simply not sufficient as the sole source of support.', 'easy', 1),

-- Q12: hard / L4 — Contradiction between representations and other evidence
(1, 'Written Representations', 'During the December 2025 audit of Meridian Capital Partners, the engagement team at Ashford & Beckett discovers that management''s representation letter states no related-party transactions occurred, but inspection of board minutes reveals a $2 million loan to the CEO. The audit team assesses the implications of this contradiction. Under AU-C 580, when representations are inconsistent with other audit evidence, the auditor should:', '["Accept the written representation as authoritative over the board minutes", "Disregard the board minutes since they are not a form of written representation", "Document the inconsistency and proceed to issue an unmodified opinion", "Perform additional procedures to resolve the matter and reconsider the reliability of management''s representations overall"]'::jsonb, 3, 'Under AU-C 580.17, if the auditor identifies that written representations are inconsistent with other audit evidence, the auditor should perform audit procedures to attempt to resolve the matter and reconsider the reliability of representations as a whole. Accepting the letter as authoritative is incorrect because the auditor must exercise professional skepticism per AU-C 200 and cannot subordinate contradictory documentary evidence to management assertions.', 'hard', 4),

-- Q13: medium / L3 — Representation about unrecorded liabilities
(1, 'Written Representations', 'While preparing the management representation letter for Redwood Financial Services'' December 2025 audit, the engagement partner at Barrett & Associates asks management about unrecorded items. Under AU-C 580, management should represent that:', '["There are no material liabilities or contingencies that have not been properly disclosed or recorded", "The auditor has already identified all unrecorded liabilities through substantive procedures", "Only liabilities confirmed by third parties are required to be recorded", "Unrecorded items below the planning materiality threshold need not be disclosed"]'::jsonb, 0, 'Under AU-C 580.11, management must represent completeness of information, which includes disclosing all liabilities and contingencies requiring recognition or disclosure. Claiming the auditor has already found all unrecorded items is incorrect because this shifts responsibility to the auditor and contradicts the principle that management has primary knowledge of the entity''s obligations.', 'medium', 3),

-- Q14: easy / L1 — Management's responsibility for internal control
(1, 'Written Representations', 'Under AU-C 580, what does management represent regarding internal control?', '["That the auditor designed the entity''s internal control system", "Its responsibility for the design, implementation, and maintenance of internal control relevant to financial reporting", "That internal controls will detect every instance of fraud or error", "That the auditor has tested every internal control in place"]'::jsonb, 1, 'Under AU-C 580.10, management represents its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements. Claiming the auditor designed the controls is incorrect because internal control is management''s responsibility, and the auditor evaluates controls as part of risk assessment without designing or implementing them.', 'easy', 1),

-- Q15: hard / L4 — "To the best of our knowledge and belief" qualifier
(1, 'Written Representations', 'During the December 2025 audit of Summit Aerospace Corp., the CEO insists on qualifying several representations in the letter with the phrase "to the best of our knowledge and belief." The engagement partner at Caldwell & Dean evaluates the appropriateness of this language. Under AU-C 580, the qualifier "to the best of our knowledge and belief" is:', '["Never acceptable because it introduces ambiguity into all representations", "Acceptable only when the SEC specifically requires it for public registrants", "Acceptable for representations about matters where management''s knowledge is the relevant factor", "Required for all representations to limit management''s legal exposure"]'::jsonb, 2, 'Under AU-C 580.A8, certain representations are appropriately limited to matters of which management has knowledge. For example, fraud representations may use this qualifier because management may not be aware of all instances. Requiring the qualifier for all representations is incorrect because factual assertions — such as having provided complete access to records — should be stated without qualification, as the qualifier would weaken their evidentiary value.', 'hard', 4),

-- Q16: hard / L3 — Noncompliance with laws and regulations disclosure
(1, 'Written Representations', 'The engagement team at Thornton & Associates is finalizing the representation letter for Copperfield Mining''s December 2025 audit. Copperfield operates under environmental regulations that directly affect line items in the financial statements. The team considers what compliance representation to include. Under AU-C 580, management should represent that:', '["The auditor has assessed compliance with all environmental laws", "Compliance with laws is outside the scope of the management representation letter", "The entity has complied with only those laws identified by the auditor", "All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in the financial statements have been disclosed"]'::jsonb, 3, 'Under AU-C 580.11, management must disclose all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements. Asserting that compliance is outside the letter''s scope is incorrect because the standard specifically requires this disclosure, placing the obligation on management rather than the auditor to identify and report such matters.', 'hard', 3),

-- Q17: easy / L1 — Assertions addressed by written representations
(1, 'Written Representations', 'Under AU-C 580, written representations from management address which categories of financial statement assertions?', '["Recognition, measurement, presentation, and disclosure", "Only existence and valuation assertions", "Only assertions related to cash and receivables", "Only assertions that the auditor was unable to test independently"]'::jsonb, 0, 'Under AU-C 580.10-.12, management''s written representations address matters across all financial statement assertions — recognition, measurement, presentation, and disclosure. The representations are comprehensive, covering the entire set of financial statements. Limiting them to only untested assertions is incorrect because management must affirm responsibility for all assertions, not just those the auditor could not independently verify.', 'easy', 1),

-- Q18: medium / L3 — Side agreements and oral understandings
(1, 'Written Representations', 'During the December 2025 audit of Harborview Distributors, the engagement partner at Ainsley & Cook suspects the entity may have oral side agreements with key vendors that modify written contract terms. The partner considers what representation to request. Under AU-C 580, the auditor should obtain a representation that management has disclosed:', '["Only formal written contracts exceeding a specified dollar threshold", "All side agreements, amendments, or oral understandings that modify the terms of reported agreements", "Only side agreements that have been approved by the board of directors", "Only contracts that the auditor specifically identified during testing"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that it has provided complete information, including disclosure of any arrangements that could affect the financial statements. Limiting disclosure to formal contracts is incorrect because side agreements or oral understandings that modify written contracts can change the substance of transactions and must be disclosed to avoid unrecorded obligations or misclassified revenue.', 'medium', 3),

-- Q19: medium / L2 — Disclosure of financial guarantees
(1, 'Written Representations', 'The engagement team at Holloway & Sims is drafting the management representation letter for Canfield Enterprises'' December 2025 audit. The entity has issued financial guarantees for a subsidiary''s debt. Under AU-C 580, the representation letter should include a statement that management has disclosed:', '["Arrangements where payment has already been made under the commitment", "Financial commitments issued exclusively to unrelated third parties", "All financial guarantees, whether written or oral, including those on behalf of related parties", "Contingent obligations that individually exceed 10% of total assets"]'::jsonb, 2, 'Under AU-C 580.11, management must disclose all arrangements, including guarantees, that could give rise to contingent liabilities or off-balance-sheet obligations regardless of whether they have been called upon. Restricting disclosure to guarantees where payments have already been made is incorrect because uncalled guarantees still represent potential obligations that may require recognition or disclosure under ASC 460.', 'medium', 2),

-- Q20: hard / L4 — Group audit and component management representations
(1, 'Written Representations', 'Douglas & Associates is the group engagement partner for Pinnacle Holdings'' December 2025 consolidated audit. Pinnacle has three wholly owned subsidiaries, each with its own management team. The group engagement partner considers whether representations from subsidiary management are necessary. Under AU-C 600, in a group audit, written representations should be obtained from:', '["Only group management, since they oversee all subsidiaries", "Only the subsidiary with the largest revenue contribution", "Only subsidiaries where the component auditor identified material misstatements", "Both group management and component management, as appropriate to the circumstances"]'::jsonb, 3, 'Under AU-C 600.41, the group engagement partner should request group management to provide written representations and may also request representations from component management as appropriate. Relying solely on group management is incorrect because when subsidiaries have separate management teams making financial reporting decisions, their representations provide evidence about component-level assertions that group management may not have direct knowledge of.', 'hard', 4),

-- Q21: easy / L1 — Primary purpose of written representations
(1, 'Written Representations', 'Under AU-C 580, what is the primary purpose of obtaining written representations from management?', '["To confirm certain matters and support other audit evidence obtained during the engagement", "To serve as the auditor''s primary defense in litigation", "To transfer all audit risk from the auditor to management", "To fulfill a regulatory filing requirement with the SEC"]'::jsonb, 0, 'Under AU-C 580.03, the objectives of obtaining written representations are to confirm management''s responsibility for the financial statements and to support other audit evidence. Characterizing the letter as transferring audit risk is incorrect because management and the auditor have shared but distinct responsibilities, and the representation letter does not shift the auditor''s obligation to obtain sufficient appropriate evidence.', 'easy', 1),

-- Q22: medium / L2 — Representations from those charged with governance
(1, 'Written Representations', 'During the December 2025 audit of Cliffside Holdings, the engagement partner at Monroe & West determines that certain representations are within the purview of the board rather than operating management. Under AU-C 580, the auditor may need to obtain written representations from:', '["Only the CEO and CFO, in all circumstances", "Those charged with governance, when matters are within their responsibility and knowledge", "External regulatory agencies that oversee the entity", "The entity''s external legal counsel on behalf of the board"]'::jsonb, 1, 'Under AU-C 580.09, the auditor requests written representations from management with appropriate responsibilities. When certain matters fall under the oversight of those charged with governance, the auditor may need representations from the board or audit committee. Restricting all representations to the CEO and CFO is incorrect because matters such as approval of related-party transactions are governed at the board level and require board-level acknowledgment.', 'medium', 2),

-- Q23: medium / L2 — Plans and intentions affecting carrying values
(1, 'Written Representations', 'Cedar Point Manufacturing is audited by Fleming & Hayes for the year ended December 2025. Cedar Point holds a large investment portfolio whose classification depends on management''s intent to hold or sell. Under AU-C 580, management should represent:', '["That the auditor has classified all investments on behalf of the entity", "That only investments exceeding materiality require intent-based classification", "Its plans, intentions, and ability to carry out specific courses of action that may affect carrying values of assets or liabilities", "That management has no obligation to disclose plans not yet approved by the board"]'::jsonb, 2, 'Under AU-C 580.A12, management''s plans and intentions are relevant when they affect the valuation or classification of assets and liabilities. Investment classification under ASC 320 depends on management''s intent and ability to hold securities. Claiming the auditor classifies investments is incorrect because classification is management''s responsibility, and the auditor cannot independently verify intent without this representation.', 'medium', 2),

-- Q24: medium / L3 — Effect of a specific representation refusal on audit opinion
(1, 'Written Representations', 'During the December 2025 audit of Stratos Engineering, management provides all required written representations but refuses to include a representation about compliance with environmental regulations, citing ongoing regulatory uncertainty. The engagement partner at Clifton & Ross evaluates the audit impact. Under AU-C 580, when management refuses a specific requested representation, the auditor should:', '["Accept the remaining representations and issue an unmodified opinion", "Withdraw from the engagement immediately", "Suspend all fieldwork until the representation is obtained", "Evaluate whether the refusal casts doubt on management''s integrity and consider the effect on the audit opinion"]'::jsonb, 3, 'Under AU-C 580.20, if management does not provide one or more requested written representations, the auditor should discuss the matter with management, reevaluate management''s integrity, and evaluate the effect on the opinion. Accepting the remaining representations without further inquiry is incorrect because a specific refusal may indicate a scope limitation or raise questions about management''s willingness to take responsibility for the financial statements.', 'medium', 3),

-- Q25: medium / L3 — Going concern representation
(1, 'Written Representations', 'The engagement partner at Whitfield & James is completing the December 2025 audit of Atlas Supply Chain, which has experienced declining revenue for three consecutive quarters. The partner requests a going-concern representation. Under AU-C 580, management should represent that:', '["Its plans to mitigate conditions that raise substantial doubt about the entity''s ability to continue as a going concern have been disclosed", "The auditor is responsible for evaluating going concern without management input", "Going-concern assumptions do not need to be addressed in the representation letter", "Only the board of directors is authorized to make going-concern representations"]'::jsonb, 0, 'Under AU-C 580.12 and AU-C 570, when conditions raise substantial doubt about going concern, management should represent that its plans to address those conditions have been disclosed to the auditor. Asserting that the auditor evaluates going concern without management input is incorrect because management''s plans, intentions, and feasibility assessments are central to the auditor''s going-concern evaluation.', 'medium', 3),

-- Q26: easy / L1 — Representations complement other evidence
(1, 'Written Representations', 'Under AU-C 580, how do written representations relate to other forms of audit evidence?', '["They replace the need for substantive testing when management is credible", "They complement other audit evidence but do not replace the need for other procedures", "They are the only form of evidence required for assertions about estimates", "They override conflicting evidence from third-party confirmations"]'::jsonb, 1, 'Under AU-C 580.04, written representations provide necessary but not sufficient audit evidence. They complement other audit procedures such as inspection, confirmation, and analytical procedures. Suggesting that representations replace substantive testing is incorrect because even when management is highly credible, the auditor must still corroborate representations with independent evidence to satisfy the sufficiency requirement.', 'easy', 1),

-- Q27: hard / L4 — Obtaining representations when management changes after balance sheet date
(1, 'Written Representations', 'Trident Systems'' CEO and CFO both resigned on January 15, 2026, after the December 31, 2025 balance sheet date. New executives were appointed on February 1, 2026. The engagement partner at Grayson & Foster must obtain the management representation letter before issuing the report on March 10, 2026. Under AU-C 580, the auditor should:', '["Waive the representation letter requirement since the original management is unavailable", "Issue a disclaimer of opinion because prior management cannot provide representations", "Obtain representations from current management covering the periods of the financial statements, even though they were not in their roles during those periods", "Delay the audit indefinitely until the former CEO and CFO are available to sign"]'::jsonb, 2, 'Under AU-C 580.19, when current management was not present during all periods covered by the auditor''s report, the auditor still requests written representations from current management, who take responsibility for the financial statements upon accepting their positions. Waiving the requirement is incorrect because AU-C 580 does not permit the auditor to forgo the representation letter; it remains a mandatory element of every audit engagement.', 'hard', 4),

-- Q28: medium / L2 — Representation about environmental liabilities
(1, 'Written Representations', 'Evergreen Chemicals is audited by Harmon & Blake for the year ended December 2025. The entity operates facilities subject to EPA remediation requirements. The engagement partner includes a specific representation about environmental matters. Under AU-C 580, this representation should address:', '["Remediation costs that have already been paid in prior periods", "Environmental matters currently subject to active litigation", "Environmental liabilities that individually exceed the materiality threshold", "All known or probable environmental liabilities and remediation obligations, whether accrued or requiring disclosure"]'::jsonb, 3, 'Under AU-C 580.11, management must disclose all known liabilities and contingencies, including environmental remediation obligations. This includes both accrued amounts and those requiring note disclosure under ASC 450. Limiting the representation to amounts above materiality is incorrect because even individually immaterial items may be material in the aggregate and require proper disclosure.', 'medium', 2),

-- Q29: medium / L2 — Representation about uncertain tax positions
(1, 'Written Representations', 'Keystone Retail Group is audited by Dalton & Associates for the year ended December 2025. Keystone has taken several aggressive tax positions that involve measurement uncertainty. The engagement partner includes a tax-related representation in the letter. Under AU-C 580, management should represent that:', '["It has properly identified and disclosed all uncertain tax positions requiring evaluation under the applicable tax framework", "Only positions formally approved by the IRS need to be disclosed in the representation letter", "The auditor is solely responsible for evaluating all tax positions taken by the entity", "Tax positions are explicitly excluded from the scope of the representation letter"]'::jsonb, 0, 'Under AU-C 580.12, management should represent that it has identified and disclosed all matters relevant to the financial statements, including uncertain tax positions evaluated under ASC 740-10. Asserting that only IRS-approved positions require disclosure is incorrect because uncertain positions — those where the likelihood of being sustained involves judgment — may also require reserves or note disclosures in the financial statements.', 'medium', 2),

-- Q30: hard / L4 — Evaluating collective reliability of representations
(1, 'Written Representations', 'During the December 2025 audit of Vanguard Industries, the engagement partner at Whitmore & Dean obtains a management representation letter that confirms all standard assertions. However, during the audit, the team identified three instances where management''s initial oral explanations were later contradicted by documentary evidence. The partner considers the overall reliability of the representations. Under AU-C 580, the auditor should:', '["Accept the signed representation letter as conclusive evidence that resolves all contradictions", "Evaluate whether the contradictions, taken collectively, cast doubt on the reliability of management''s representations and consider the effect on the overall audit", "Request that management rewrite the representation letter to match the documentary evidence", "Withdraw from the engagement because three contradictions automatically indicate fraud"]'::jsonb, 1, 'Under AU-C 580.17-.18, when the auditor has concerns about the reliability of written representations, the auditor should evaluate the contradictions collectively and determine whether they affect the overall reliability of management''s assertions. Withdrawing because contradictions automatically indicate fraud is incorrect because the auditor must investigate further per AU-C 240 before reaching such a conclusion — inconsistencies may have legitimate explanations.', 'hard', 4)
;

COMMIT;
